import type { TextBloomOptions } from './text-bloom.motion.js';

export type { TextBloomVoice } from './text-bloom.motion.js';

export interface TextBloomProps extends TextBloomOptions {
    /** Plain text, kept readable once while its segments animate. */
    text: string;
    /** Segment by words or Unicode code points. @default 'word' */
    by?: 'word' | 'character';
    /** Semantic HTML root. @default 'span' */
    as?: keyof HTMLElementTagNameMap;
}

/** Vue component refs expose the root DOM element, null when presence removes it. */
export interface KidaElement {
    element: HTMLElement | null;
}

[data-kida-text-bloom-segment] {
  display: inline-block;
}

@media (prefers-reduced-motion: reduce) {
  [data-kida-text-bloom-segment] {
    /* biome-ignore lint/complexity/noImportantStyles: overrides the SSR inline initial state */
    opacity: 1 !important;
    /* biome-ignore lint/complexity/noImportantStyles: overrides the SSR inline initial state */
    transform: none !important;
  }
}

import { animate, inView, stagger } from 'motion'
import { prefersReducedMotion } from './reduced-motion.motion.js'

export type TextBloomVoice = 'gentle' | 'pop'

export interface TextBloomOptions {
  /** Motion character. @default 'gentle' */
  voice?: TextBloomVoice
  /** Seconds between segments. @default 0.045 */
  stagger?: number
  /** Seconds before the first segment. @default 0 */
  delay?: number
  /** Seconds per segment. @default 0.55 */
  duration?: number
  /** Animate only on the first viewport entry. @default true */
  once?: boolean
  /** How much of the root must be visible. @default 0.4 */
  amount?: 'some' | 'all' | number
}

const DEFAULTS = {
  voice: 'gentle',
  stagger: 0.045,
  delay: 0,
  duration: 0.55,
  once: true,
  amount: 0.4,
} as const

export function textBloomInitialStyle(voice: TextBloomVoice = 'gentle') {
  return {
    opacity: 0,
    transform:
      voice === 'pop'
        ? 'translate3d(0, 18px, 0) scale(0.86)'
        : 'translate3d(0, 10px, 0) scale(0.98)',
    transformOrigin: '50% 80%',
    willChange: 'transform, opacity',
  } as const
}

export function textBloom(element: HTMLElement, options: TextBloomOptions = {}): () => void {
  const settings = {
    voice: options.voice ?? DEFAULTS.voice,
    stagger: options.stagger ?? DEFAULTS.stagger,
    delay: options.delay ?? DEFAULTS.delay,
    duration: options.duration ?? DEFAULTS.duration,
    once: options.once ?? DEFAULTS.once,
    amount: options.amount ?? DEFAULTS.amount,
  }
  const segments = [...element.querySelectorAll<HTMLElement>('[data-kida-text-bloom-segment]')]
  if (segments.length === 0) return () => {}

  const hide = () => {
    for (const segment of segments)
      Object.assign(segment.style, textBloomInitialStyle(settings.voice))
    element.dataset.state = 'idle'
  }
  const settle = () => {
    for (const segment of segments) {
      segment.style.opacity = '1'
      segment.style.transform = 'none'
      segment.style.transformOrigin = ''
      segment.style.willChange = 'auto'
    }
    element.dataset.state = 'settled'
  }

  if (prefersReducedMotion()) {
    settle()
    return () => {}
  }

  hide()
  let controls: ReturnType<typeof animate> | undefined
  let settleFrame = 0

  const cancelSettle = () => {
    if (!settleFrame) return
    cancelAnimationFrame(settleFrame)
    settleFrame = 0
  }

  const stop = inView(
    element,
    () => {
      cancelSettle()
      element.dataset.state = 'active'
      const pop = settings.voice === 'pop'
      controls = animate(
        segments,
        {
          opacity: pop ? [0, 1, 1, 1] : [0, 1, 1],
          transform: pop
            ? [
                'translate3d(0, 18px, 0) scale(0.86)',
                'translate3d(0, -4px, 0) scale(1.08)',
                'translate3d(0, 1px, 0) scale(0.985)',
                'translate3d(0, 0, 0) scale(1)',
              ]
            : [
                'translate3d(0, 10px, 0) scale(0.98)',
                'translate3d(0, 0, 0) scale(1)',
                'translate3d(0, 0, 0) scale(1)',
              ],
        },
        {
          duration: settings.duration,
          delay: stagger(settings.stagger, { startDelay: settings.delay }),
          // Pop reaches its visible overshoot early, then recoils once before settling.
          ease: pop
            ? [
                [0.16, 1, 0.3, 1],
                [0.4, 0, 0.6, 1],
                [0.16, 1, 0.3, 1],
              ]
            : [0.16, 1, 0.3, 1],
          times: pop ? [0, 0.45, 0.72, 1] : [0, 0.72, 1],
        },
      )

      const currentControls = controls
      void currentControls.finished
        .then(() => {
          // `animate()` creates one animation per property and segment. Wait for the whole
          // group, then move one frame past Motion's final style commits before cleaning up.
          if (controls !== currentControls) return
          settleFrame = requestAnimationFrame(() => {
            settleFrame = 0
            if (controls === currentControls) settle()
          })
        })
        .catch(() => {
          // Cancelling a pass rejects its finished promise; the exit cleanup re-arms it.
        })

      if (settings.once) stop()
      return settings.once
        ? undefined
        : () => {
            cancelSettle()
            controls?.cancel()
            hide()
          }
    },
    { amount: settings.amount },
  )

  return () => {
    stop()
    cancelSettle()
    controls?.cancel()
  }
}

const QUERY = '(prefers-reduced-motion: reduce)'

/**
 * Whether the user has asked for reduced motion.
 *
 * SSR-safe: returns `false` when there is no `window`, matching the CSS default
 * (the `prefers-reduced-motion` media query in `@kida-ui/styles` is the real guard;
 * this is for the JS-driven paths that CSS cannot express).
 */
export function prefersReducedMotion(): boolean {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return false
  return window.matchMedia(QUERY).matches
}

/**
 * Subscribe to changes of the reduced-motion preference.
 * Returns an unsubscribe function. No-op (and immediately unsubscribable) on the server.
 */
export function watchReducedMotion(onChange: (reduced: boolean) => void): () => void {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return () => {}

  const list = window.matchMedia(QUERY)
  const handler = (event: MediaQueryListEvent) => onChange(event.matches)
  list.addEventListener('change', handler)
  return () => list.removeEventListener('change', handler)
}
